use spark_engine::arms;
#[allow(dead_code)] #[path="../src/hybrid/plan.rs"] mod plan; #[allow(dead_code)] #[path="../src/hybrid/linear.rs"] mod linear;
#[test] fn typed_fp8_load_selection() { use engine_model::{plan::{ModelPlan,Format},shapes::{Ffn,ExpertStorage,Residual}}; let mut p=ModelPlan::from_config(include_bytes!("../../model/tests/fixtures/qwen/Qwen3.6-35B-A3B-FP8.config.json")).unwrap(); assert!(!plan::uses_typed_loader(&p)); for l in &mut p.shape.layers { if let Ffn::Experts(e)=&mut l.ffn { e.storage=ExpertStorage::PerExpert; } } assert!(plan::uses_typed_loader(&p)); let mut other=p.clone(); other.format=Format::Bf16; assert!(!plan::uses_typed_loader(&other)); other=p.clone(); other.shape.residual=Residual::Streams{count:4,rank:320}; assert!(!plan::uses_typed_loader(&other)); other=p.clone(); other.shape.layers.clear(); assert!(!plan::uses_typed_loader(&other)); }
#[test] fn bf16_preparation_rows() { for n in [1,4,8,32,64,256,248320] { assert!(linear::bf16_rows_supported(n)); } for n in [0,2,3,5,63,65] { assert!(!linear::bf16_rows_supported(n)); } }
#[test] fn typed_world_two_is_unconditionally_refused() { assert!(plan::require_world(1).is_ok()); for size in [0,2,4,usize::MAX] { assert_eq!(plan::require_world(size).unwrap_err(), "hybrid currently requires world size 1"); } }
#[test] fn norm_launch_choices_are_pinned() {
    for (rows, four, expected) in [(1,false,(128,2)),(1,true,(128,1)),(2,false,(256,0)),(255,false,(256,0)),(256,true,(256,1)),(4096,true,(256,1)),(32768,true,(256,1))] { assert_eq!(linear::norm_launch(false,true,rows,None,four),expected); assert_eq!(linear::norm_launch(false,false,rows,None,four),(128,expected.1)); for order in [None,Some(0),Some(1),Some(2)] { assert_eq!(linear::norm_launch(true,true,rows,order,four),(128,2)); assert_eq!(linear::norm_launch(true,false,rows,order,four),(128,2)); } for order in [0,1,2] { assert_eq!(linear::norm_launch(false,true,rows,Some(order),four),(expected.0,order)); assert_eq!(linear::norm_launch(false,false,rows,Some(order),four),(128,order)); } }
}
